static float clip(float value, float lower, float upper)
{
    if (value < lower) return lower;
    if (value > upper) return upper;
    return value;
}

static float elu(float value)
{
    return value >= 0.0f ? value : expf(value) - 1.0f;
}

static void linear_elu(
    const float *input, size_t input_size, float *output, size_t output_size,
    const float *weight, const float *bias)
{
    size_t row;
    size_t column;
    for (row = 0; row < output_size; ++row) {
        float sum = bias[row];
        const float *row_weight = weight + row * input_size;
        for (column = 0; column < input_size; ++column) {
            sum += row_weight[column] * input[column];
        }
        output[row] = elu(sum);
    }
}

void g1_assist_v8_history_reset(
    G1AssistV8History *history,
    const float initial_position_rad[2],
    const float initial_velocity_rad_s[2])
{
    unsigned int frame;
    unsigned int side;
    if (history == NULL || initial_position_rad == NULL || initial_velocity_rad_s == NULL) return;
    for (frame = 0; frame < G1_ASSIST_V8_HISTORY_LENGTH; ++frame) {
        for (side = 0; side < 2; ++side) {
            history->position_rad[frame][side] = initial_position_rad[side];
            history->velocity_rad_s[frame][side] = initial_velocity_rad_s[side];
            history->smoothed_torque_nm[frame][side] = 0.0f;
        }
    }
    for (frame = 0; frame < 25; ++frame)
        for (side = 0; side < 20; ++side) history->pulse_state[frame][side] = 0.0f;
    history->next_index = 0U;
}

void g1_assist_v8_history_append(
    G1AssistV8History *history,
    const float position_rad[2],
    const float velocity_rad_s[2],
    const float previous_smoothed_torque_nm[2], const float pulse_state[20])
{
    unsigned int side;
    unsigned int index;
    if (history == NULL || position_rad == NULL || velocity_rad_s == NULL || previous_smoothed_torque_nm == NULL) return;
    index = history->next_index;
    for (side = 0; side < 2; ++side) {
        history->position_rad[index][side] = position_rad[side];
        history->velocity_rad_s[index][side] = velocity_rad_s[side];
        history->smoothed_torque_nm[index][side] = previous_smoothed_torque_nm[side];
    }
    for (side = 0; side < 20; ++side) history->pulse_state[index][side] = pulse_state[side];
    history->next_index = (index + 1U) % G1_ASSIST_V8_HISTORY_LENGTH;
}

void g1_assist_v8_history_build_observation(
    const G1AssistV8History *history,
    float observation[G1_ASSIST_V8_INPUT_SIZE])
{
    unsigned int frame;
    unsigned int side;
    if (history == NULL || observation == NULL) return;
    for (frame = 0; frame < G1_ASSIST_V8_HISTORY_LENGTH; ++frame) {
        unsigned int source = (history->next_index + frame) % G1_ASSIST_V8_HISTORY_LENGTH;
        for (side = 0; side < 2; ++side) {
            observation[frame * 2U + side] = history->position_rad[source][side];
            observation[50U + frame * 2U + side] = history->velocity_rad_s[source][side];
            observation[100U + frame * 2U + side] = history->smoothed_torque_nm[source][side];
        }
        for (side = 0; side < 20; ++side) observation[150U + frame * 20U + side] = history->pulse_state[source][side];
    }
}

void g1_assist_v8_policy_forward(
    const float observation[G1_ASSIST_V8_INPUT_SIZE],
    float action[G1_ASSIST_V8_OUTPUT_SIZE],
    G1AssistV8Workspace *workspace)
{
    size_t index;
    size_t row;
    size_t column;
    if (observation == NULL || action == NULL || workspace == NULL) return;
    for (index = 0; index < G1_ASSIST_V8_INPUT_SIZE; ++index) {
        workspace->secondary_650[index] =
            (observation[index] - OBS_MEAN[index]) / (OBS_STD[index] + NORMALIZER_EPS);
    }
    linear_elu(workspace->secondary_650, 650, workspace->hidden_256, 256, WEIGHT_0, BIAS_0);
    linear_elu(workspace->hidden_256, 256, workspace->secondary_650, 64, WEIGHT_1, BIAS_1);
    linear_elu(workspace->secondary_650, 64, workspace->hidden_256, 16, WEIGHT_2, BIAS_2);
    for (row = 0; row < G1_ASSIST_V8_OUTPUT_SIZE; ++row) {
        float sum = BIAS_3[row];
        const float *row_weight = WEIGHT_3 + row * 16U;
        for (column = 0; column < 16; ++column) sum += row_weight[column] * workspace->hidden_256[column];
        action[row] = sum;
    }
}


static float pulse_step(G1AssistV8Controller *c, const float action[2], const float p[2])
{
    float *s=c->pulse;
    float delta=c->filtered_velocity[0]-c->filtered_velocity[1];
    float direction=(delta<-.12f && c->filtered_velocity[0]<-.08f) ? -1.0f :
        (delta>.12f && c->filtered_velocity[1]<-.08f) ? 1.0f : 0.0f;
    if(direction!=s[6]) { s[10]=p[0]; s[11]=p[1]; }
    c->displacement[0]=s[10]-p[0]; c->displacement[1]=s[11]-p[1];
    s[12]=fminf(s[12]+.01f,1.5f);
    if(s[12]>=1.5f-1e-6f) {s[13]=0;s[17]=0;}
    int walking=s[13]!=0;
    float threshold=walking ? 0.04363323129985824f : 0.05235987755982989f;
    float travel=c->displacement[direction<0 ? 0 : 1];
    s[7]=direction==s[6] ? fminf(s[7]+.01f,.06f) : .01f;
    s[6]=direction;
    int confirmed=s[7]>=.03f-1e-6f;
    int qualified=confirmed && direction!=0 && travel>=threshold;
    int event=qualified && direction!=s[13];
    float interval=s[12];
    if(event && walking && interval>=.2f && interval<=1.2f) {
        s[14]=s[17]>0 ? .5f*s[14]+.5f*interval : interval;s[17]=1;
    }
    if(event) {s[12]=0;s[13]=direction;}
    int quiet=fmaxf(fabsf(c->filtered_velocity[0]),fabsf(c->filtered_velocity[1]))<.04f;
    s[9]=quiet ? fminf(s[9]+.01f,.3f) : 0;
    int active=s[1]!=0, releasing=s[3]>0;
    int lowering=(s[1]<0 ? c->filtered_velocity[0] : c->filtered_velocity[1])>.12f;
    int reverse=s[7]>=.06f-1e-6f && direction!=0 && direction!=s[1];
    int quiet_end=s[9]>=.3f-1e-6f && s[0]>=.5f;
    int timed_end=s[0]>=s[8]-s[16]-1e-6f;
    if(active && !releasing && (lowering || reverse || quiet_end || timed_end)) {
        float tail=fmaxf(3.141592653589793f*fabsf(c->previous[0])/160.f+.01f,.02f);
        s[16]=fminf(s[16],tail);
        s[3]=.01f; s[4]=fabsf(c->previous[0]);
    }
    releasing=s[3]>0;
    if(!active && confirmed && direction==0) s[5]=0;
    if(!active && qualified && direction!=s[5]) {
        s[0]=0; s[1]=direction; s[2]=.5f*(clip(action[0],-1,1)+1)*10;
        s[8]=.6f+.5f*(clip(action[1],-1,1)+1)*(1.4f-.6f);
        if(s[17]>0) s[8]=fminf(s[8],clip(.85f*s[14],.3f,1.4f));
        s[15]=fminf(.2f,.45f*s[8]);s[16]=fminf(.25f,.45f*s[8]);
        s[2]=fminf(s[2],160.f*fminf(s[15],s[16])/3.141592653589793f);
        s[5]=direction; s[3]=s[4]=0;
    }
    active=s[1]!=0;
    if(active) s[0]+=.01f;
    float rise=clip(s[0]/fmaxf(s[15],.01f),0,1), rp=clip(s[3]/fmaxf(s[16],.01f),0,1);
    float wave=releasing ? cosf(1.5707963267948966f*rp) : sinf(1.5707963267948966f*rise);
    float magnitude=(releasing ? s[4] : s[2])*wave*wave;
    float result=active ? s[1]*magnitude : 0;
    int done=active && releasing && s[3]>=s[16]-1e-6f;
    if(done) { result=0; for(int i=0;i<5;++i) s[i]=0; s[8]=0; }
    if(releasing && !done) s[3]+=.01f;
    return result;
}

static int finite_pair(const float *x)
{
    return x != NULL && isfinite(x[0]) && isfinite(x[1]);
}
void g1_assist_v8_stop(G1AssistV8Controller *c, float out[2])
{
    if (out != NULL) out[0] = out[1] = 0.0f;
    if (c == NULL) return;
    c->ready = 0U;
    c->displacement[0]=c->displacement[1]=0;
    for (size_t i=0; i<18; ++i) c->pulse[i]=0.0f;
    c->previous[0] = c->previous[1] = 0.0f;
    c->filtered_velocity[0] = c->filtered_velocity[1] = 0.0f;
}
int g1_assist_v8_reset(G1AssistV8Controller *c, const float p[2], const float v[2])
{
    if (c == NULL) return -1;
    g1_assist_v8_stop(c, NULL);
    if (!finite_pair(p) || !finite_pair(v)) return -1;
    g1_assist_v8_history_reset(&c->history, p, v);
    c->first = 1U;
    c->ready = 1U;
    return 0;
}
int g1_assist_v8_step(G1AssistV8Controller *c, const float p[2], const float v[2], int enabled, float out[2])
{
    float action[2], state[20], output;
    const float scale[18]={1.4f,1,10,.25f,10,1,1,.06f,1.4f,.3f,.1f,.1f,1.5f,1,1.2f,.2f,.25f,1};
    size_t side;
    if (c == NULL || out == NULL) {
        g1_assist_v8_stop(c, out);
        return -1;
    }
    out[0] = out[1] = 0;
    if (!enabled || !c->ready) {
        g1_assist_v8_stop(c, out);
        return 1;
    }
    if (!finite_pair(p) || !finite_pair(v)) {
        g1_assist_v8_stop(c, out);
        return -1;
    }
    if (c->first) g1_assist_v8_history_reset(&c->history, p, v);
    else {
        for (side=0; side<18; ++side) state[side]=c->pulse[side]/scale[side];
        state[10]=c->displacement[0]/.1f; state[11]=c->displacement[1]/.1f;
        state[18]=c->filtered_velocity[0]; state[19]=c->filtered_velocity[1];
        g1_assist_v8_history_append(&c->history, p, v, c->previous, state);
    }
    c->first = 0U;
    g1_assist_v8_history_build_observation(&c->history, c->observation);
    g1_assist_v8_policy_forward(c->observation, action, &c->workspace);
    if (!finite_pair(action)) {
        g1_assist_v8_stop(c, out);
        return -1;
    }
    for (side = 0; side < 2; ++side) {
        c->filtered_velocity[side] += (1.0f-expf(-0.01f/0.03f)) * (v[side]-c->filtered_velocity[side]);
    }
    output = pulse_step(c, action, p);
    c->previous[0]=output; c->previous[1]=-output;
    out[0]=output; out[1]=-output;
    return 0;
}

